<?php if(!defined('SW_APP')){http_response_code(404);exit;}$rows=all("SELECT r.id,r.title,r.finalized_at AS closed_at,COALESCE(e.revealed_number,w.winning_number) AS ticket_number,r.draw_outcome,r.draw_version,(SELECT COUNT(*) FROM prize_awards a WHERE a.raffle_id=r.id) AS award_count,w.claim_status,e.sha256 AS archive_sha256,e.published_at,p.name FROM raffles r LEFT JOIN winners w ON w.raffle_id=r.id LEFT JOIN raffle_evidence e ON e.raffle_id=r.id LEFT JOIN participants p ON p.id=w.participant_id AND p.raffle_id=w.raffle_id AND p.number=w.winning_number WHERE r.status='finalizado' ORDER BY r.finalized_at DESC,r.id DESC");?>
<div class="page-heading"><p class="eyebrow">RESULTADOS</p><h1>Ganadores</h1><p>Consulta el resultado de los sorteos finalizados.</p></div><section class="panel"><div class="section-heading"><h2>Resultados y premios</h2><p>Resultados de los sorteos cerrados y premios asignados. La entrega de premios y las devoluciones requieren gestión y conciliación.</p></div><?php if(!$rows):empty_state('No hay sorteos finalizados','Cuando cierres un sorteo, aparecerá en esta sección.');else:?><div class="table-wrap"><table><thead><tr><th>Sorteo</th><th>Fecha de cierre</th><th>Boleto ganador</th><th>Ganador</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><?=h($r['closed_at']??'—')?></td><td><?=h($r['ticket_number']??'—')?></td><td><?=h((int)$r['award_count']>1?$r['award_count'].' titulares':($r['name']??'—'))?></td><td><?=h($r['draw_outcome']==='devolucion_pendiente'?'Devolución pendiente':($r['ticket_number']===null?'Sin revelar':($r['claim_status']??'Premio asignado')))?> <?php if((int)$r['draw_version']===1):?><a href="index.php?view=evidence&amp;id=<?=h($r['id'])?>">Evidencia</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php $awardRows=all("SELECT r.title,p.name,p.email,a.winning_number,a.prize_type,a.amount_cents,a.status FROM prize_awards a JOIN raffles r ON r.id=a.raffle_id JOIN participants p ON p.id=a.participant_id ORDER BY r.finalized_at DESC,a.raffle_id,a.participant_id");$refundRows=all("SELECT r.title,p.name,p.email,p.number,f.amount_cents,f.reason FROM raffle_refund_reviews f JOIN raffles r ON r.id=f.raffle_id JOIN participants p ON p.id=f.participant_id ORDER BY r.finalized_at DESC,f.raffle_id,f.participant_id");?>
<section class="panel"><div class="section-heading"><h2>Premios asignados por titular</h2><p>Importes calculados al cierre. La asignación no implica que el pago o la entrega se haya realizado.</p></div><?php if(!$awardRows):empty_state('Sin premios asignados','Aparecerán aquí los titulares pagados de los sorteos con evidencia.');else:?><div class="table-wrap"><table><thead><tr><th>Sorteo</th><th>Titular</th><th>Número</th><th>Premio asignado</th><th>Estado</th></tr></thead><tbody><?php foreach($awardRows as $a):?><tr><td><?=h($a['title'])?></td><td><?=h($a['name'])?><small class="muted"><?=h($a['email'])?></small></td><td><?=h(str_pad((string)$a['winning_number'],4,'0',STR_PAD_LEFT))?></td><td><?=$a['prize_type']==='producto'?'Producto':money($a['amount_cents'])?></td><td><?=h($a['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="panel"><div class="section-heading"><h2>Devoluciones pendientes de revisión</h2><p>No se ha transferido ni acreditado dinero automáticamente.</p></div><?php if(!$refundRows):empty_state('Sin devoluciones pendientes','No hay registros de revisión.');else:?><div class="table-wrap"><table><thead><tr><th>Sorteo</th><th>Titular</th><th>Número</th><th>Importe</th><th>Motivo</th></tr></thead><tbody><?php foreach($refundRows as $a):?><tr><td><?=h($a['title'])?></td><td><?=h($a['name'])?><small class="muted"><?=h($a['email'])?></small></td><td><?=h($a['number'])?></td><td><?=money($a['amount_cents'])?></td><td><?=$a['reason']==='venta_incompleta'?'Venta exclusiva incompleta':'Número sin compradores pagados'?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
